#!/usr/bin/env python3
"""Phase 3.1 dashboard: decision-first, with lazy full candidate pool."""
import html, json, os
from string import Template

ROOT=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DATA=os.path.join(ROOT,'data'); DOCS=os.path.join(ROOT,'docs')
LATEST=os.path.join(DATA,'seven_factor_latest.json'); EVENING=os.path.join(DATA,'evening_latest.json'); MORNING=os.path.join(DATA,'morning_latest.json'); OUT=os.path.join(DOCS,'index.html')

def esc(v): return html.escape(str(v if v is not None else '-'))
def num(v,d=0):
    try:return float(v)
    except:return d
def pct(v):return f'{num(v):+.1f}%'
def cls(v):return 'up' if num(v)>=0 else 'down'
def load(p):
    if not os.path.exists(p):return {}
    try:
        with open(p,encoding='utf-8') as f:return json.load(f)
    except:return {}

def action(s):
    n=num(s.get('sentiment_score'),50)
    if n<40:return '谨慎观察','市场偏弱，等待确认，不因为高分个股强行出手','cold'
    if n<55:return '轻仓试错','市场偏弱，优先主线与资金确认','normal'
    if n<70:return '结构性参与','围绕强板块挑核心，重点观察池优先','warm'
    return '积极参与','市场进攻条件较好，优先主线核心与首板前候选','hot'

def focus_card(r,i):
    rec=r.get('recency') or {}; hist=r.get('history') or {}; res=r.get('resonance') or {}; rc=int(num(res.get('count'),0))
    dots='●'*rc+'○'*max(0,3-rc); w=r.get('next_day_watch') or ['等待信号确认']
    return f'<article class="focus"><div class="fhead"><span class="rank">TOP {i}</span><div><b>{esc(r.get("name"))}</b><small>{esc(r.get("code"))} · {esc(r.get("sector","未分类"))}</small></div><strong>{num(r.get("adjusted_total")):.1f}</strong><span class="pill">P{esc(rec.get("tier","-"))}</span></div><div class="fm"><span>三共振 <b>{dots}</b></span><span>连板概率 <b>{esc(r.get("lianban_probability"))}%</b></span><span>涨幅 <b class="{cls(r.get("change_pct"))}">{pct(r.get("change_pct"))}</b></span><span>换手 <b>{esc(r.get("turnover_rate"))}%</b></span><span>历史涨停 <b>{esc(hist.get("limit_up_count"))}</b></span><span>距上次 <b>{esc(hist.get("days_since_last_lu"))}日</b></span></div><div class="watch"><b>次日重点</b><span>{esc(w[0])}</span><span>{esc(w[1]) if len(w)>1 else "-"}</span></div></article>'

def news(items,empty):
    if not items:return f'<div class="empty">{empty}</div>'
    return ''.join(f'<div class="news"><b>{esc(x.get("title",""))}</b><small>{esc(x.get("pubDate",""))}</small></div>' for x in items[:8])

def render(d,e,m):
    s=d.get('market_sentiment') or {}; c=d.get('candidates') or []; a,desc,mood=action(s)
    ordered=sorted(c,key=lambda r:(int(num((r.get('recency') or {}).get('tier'),99)),-num(r.get('adjusted_total')))); focus=[r for r in ordered if r.get('pool')=='重点观察'][:8]
    ready=sum(r.get('pool')=='预备池' for r in c); watch=sum(r.get('pool')=='观察池' for r in c)
    secs=sorted(d.get('sector_rankings') or [],key=lambda x:num(x.get('avg_change')),reverse=True)[:6]; cons=sorted(d.get('concept_rankings') or [],key=lambda x:num(x.get('avg_change')),reverse=True)[:10]
    sec=''.join(f'<div class="sector"><b>{esc(x.get("name"))}</b><span class="{cls(x.get("avg_change"))}">{pct(x.get("avg_change"))}</span><small>{esc(x.get("limit_up_count"))}涨停 · {esc(x.get("strong_count"))}强势</small></div>' for x in secs)
    con=''.join(f'<span class="concept">#{esc(x.get("rank"))} {esc(x.get("name"))} <em class="{cls(x.get("avg_change"))}">{pct(x.get("avg_change"))}</em></span>' for x in cons)
    ef=''.join(f'<span class="mini">{esc(x.get("name"))} {esc(x.get("score"))}</span>' for x in (e.get('focus_candidates') or [])[:8])
    ms='<span class="mini">已生成</span>' if m else '<span class="mini">等待08:00</span>'
    t=Template(r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>七因子 · 决策仪表盘</title><style>
:root{--bg:#0a0d12;--panel:#121720;--panel2:#171e28;--line:#283241;--text:#e8eef7;--muted:#8792a4;--blue:#6ea8ff;--up:#ff6575;--down:#35d09a;--gold:#f5c85b;--orange:#ffae5c}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif}.wrap{max-width:1480px;margin:auto;padding:22px}.top{display:flex;justify-content:space-between;gap:20px;align-items:end}.title{font-size:27px;font-weight:900}.sub,.meta,small,.muted{color:var(--muted)}.sub{margin-top:6px;font-size:12px}.meta{text-align:right;font-size:11px;line-height:1.8}.hero{display:grid;grid-template-columns:1.2fr 1fr;gap:14px;margin:16px 0}.card{background:var(--panel);border:1px solid var(--line);border-radius:15px}.decision{padding:20px}.state{display:flex;justify-content:space-between;align-items:center}.action{font-size:29px;font-weight:900}.score{font-size:40px;font-weight:900}.desc{color:var(--muted);margin:8px 0 16px}.metrics,.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.stats{grid-template-columns:1fr 1fr;padding:18px}.metric,.stat{padding:10px;background:#10151d;border:1px solid #222c38;border-radius:9px}.metric span,.stat span{display:block;color:var(--muted);font-size:10px}.metric b{display:block;margin-top:4px;font-size:17px}.stat b{font-size:25px;display:block;margin-top:4px}.up{color:var(--up)}.down{color:var(--down)}.hot{color:var(--up)}.warm{color:var(--orange)}.normal{color:var(--blue)}.cold{color:var(--down)}.section{margin:14px 0;padding:16px}.head{margin-bottom:12px}.head h2{font-size:17px;margin:0}.head p{font-size:11px;color:var(--muted);margin:4px 0 0}.focus-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.focus{background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:14px}.fhead{display:grid;grid-template-columns:48px 1fr 70px 46px;gap:8px;align-items:center}.fhead b{font-size:15px}.fhead small{display:block;font-size:9px;margin-top:3px}.fhead strong{font-size:21px;text-align:right}.rank{font-size:10px;color:var(--gold)}.pill,.mini{display:inline-flex;padding:4px 7px;border-radius:6px;background:#202932;color:#c8d3e2;font-size:9px}.fm{display:grid;grid-template-columns:repeat(6,1fr);gap:6px;margin:12px 0}.fm span{background:#10151d;border:1px solid #212b37;border-radius:7px;padding:7px;font-size:9px;color:var(--muted)}.fm b{display:block;color:var(--text);font-size:12px;margin-top:3px}.watch{display:flex;gap:8px;align-items:center;background:#0f141b;border-radius:7px;padding:8px;font-size:10px}.watch span{color:var(--muted)}.layout,.pipeline{display:grid;grid-template-columns:1.05fr .95fr;gap:14px}.sector{display:grid;grid-template-columns:1fr 70px 130px;padding:9px 10px;background:#10151d;border:1px solid #212b37;border-radius:8px;margin-bottom:7px}.concepts,.pills{display:flex;flex-wrap:wrap;gap:7px}.concept{padding:8px 9px;background:#10151d;border:1px solid #212b37;border-radius:8px;font-size:10px}.concept em{font-style:normal;margin-left:6px}.pipeline-card{padding:14px;background:#10151d;border:1px solid #222c38;border-radius:10px}.pipeline-card h3{margin:0 0 8px;font-size:13px}.news{padding:8px 0;border-bottom:1px solid #222b36}.news b{display:block;font-size:10px}.news small{font-size:9px}.empty{padding:18px;text-align:center;color:var(--muted);background:#0f141b;border-radius:8px}.toggle{display:flex;justify-content:space-between;align-items:center;cursor:pointer}.lazy{display:none}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.toolbar input,.toolbar select{background:#0f141b;border:1px solid #273140;color:var(--text);padding:8px;border-radius:8px}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:8px;border-bottom:1px solid #222b36;text-align:left;font-size:10px}.table th{color:var(--muted)}button{cursor:pointer}.footer{text-align:center;color:#5d6979;font-size:10px;padding:18px}@media(max-width:1000px){.hero,.layout,.pipeline{grid-template-columns:1fr}.focus-grid{grid-template-columns:1fr}.fm{grid-template-columns:repeat(3,1fr)}}@media(max-width:620px){.wrap{padding:12px}.top{align-items:flex-start;flex-direction:column}.meta{text-align:left}.metrics,.stats{grid-template-columns:repeat(2,1fr)}.fm{grid-template-columns:repeat(2,1fr)}.fhead{grid-template-columns:42px 1fr 60px 40px}.sector{grid-template-columns:1fr 60px}.sector small{display:none}}
</style></head><body><div class="wrap"><div class="top"><div><div class="title">七因子 · 决策仪表盘</div><div class="sub">收盘选股 → 晚间预判 → 隔夜修正 → 竞价确认 · 七因子评分独立</div></div><div class="meta">扫描 $DATE $TIME<br>模型 $MODEL</div></div>
<section class="hero"><div class="card decision"><div class="state"><div><div class="$MOOD action">$ACTION</div><div class="desc">$DESC</div></div><div style="text-align:right"><div class="score">$SCORE</div><div class="muted">情绪分 · $LABEL</div></div></div><div class="metrics"><div class="metric"><span>涨停</span><b class="up">$LUP</b></div><div class="metric"><span>跌停</span><b class="down">$LDN</b></div><div class="metric"><span>最高连板</span><b>$MAX</b></div><div class="metric"><span>炸板率</span><b>$EXP%</b></div></div></div><div class="card stats"><div class="stat"><span>重点观察</span><b>$FOCUS</b><small>明日优先</small></div><div class="stat"><span>预备池</span><b>$READY</b><small>等待确认</small></div><div class="stat"><span>观察池</span><b>$WATCH</b><small>暂不抢跑</small></div><div class="stat"><span>完整候选池</span><b>$TOTAL</b><small>折叠懒加载</small></div></div></section>
<section class="card section"><div class="head"><h2>① 明日重点观察</h2><p>先看重点池，再看完整候选池</p></div><div class="focus-grid">$FOCUS_HTML</div></section>
<section class="card section"><div class="head"><h2>② 主线与板块</h2><p>市场共识优先于个股分数</p></div><div class="layout"><div>$SECTOR</div><div><div class="concepts">$CONCEPT</div></div></div></section>
<section class="card section"><div class="head"><h2>③ 晚间预判 / 隔夜修正</h2><p>工作流尚未运行时明确显示“等待”，不伪造信息</p></div><div class="pipeline"><div class="pipeline-card"><h3>20:00 · 明日预判</h3><div class="pills">$EF</div>$EN</div><div class="pipeline-card"><h3>08:00 · 隔夜修正</h3><div class="pills">$MS</div>$MN</div></div></section>
<section class="card section"><div class="toggle" onclick="toggleFull()"><div><h2 style="margin:0;font-size:17px">④ 完整候选池</h2><div class="muted" style="font-size:10px;margin-top:5px">默认不加载 1400 只股票；点击展开后才读取 JSON，搜索/筛选/排序可用。</div></div><button id="btn" style="background:#172131;color:#bfd4f5;border:1px solid #30445f;padding:7px 10px;border-radius:8px">展开</button></div><div id="full" class="lazy"><div class="toolbar"><input id="q" placeholder="搜索股票 / 代码 / 板块"><select id="pool"><option>全部</option><option>重点观察</option><option>预备池</option><option>观察池</option><option>淘汰</option></select><select id="sort"><option value="score">调整分</option><option value="change">涨幅</option><option value="tier">优先级</option></select></div><div id="rows"><div class="empty">正在加载…</div></div></div></section>
<div class="footer">七因子决策系统 · 仅供研究参考，不构成投资建议</div></div><script>
let loaded=false,all=[];function toggleFull(){const b=document.getElementById('full'),btn=document.getElementById('btn'),open=b.style.display==='block';b.style.display=open?'none':'block';btn.textContent=open?'展开':'收起';if(!loaded&&!open){loaded=true;fetch('data/seven_factor_latest.json').then(r=>r.json()).then(d=>{all=d.candidates||[];render()}).catch(()=>document.getElementById('rows').innerHTML='<div class="empty">候选池加载失败，请刷新页面。</div>')}}function render(){const q=(document.getElementById('q').value||'').toLowerCase(),p=document.getElementById('pool').value,s=document.getElementById('sort').value;let a=all.filter(r=>(p==='全部'||r.pool===p)&&(!q||(`${r.name||''} ${r.code||''} ${r.sector||''} ${r.sw_industry||''}`).toLowerCase().includes(q)));a.sort((x,y)=>s==='change'?num(y.change_pct)-num(x.change_pct):s==='tier'?num(x.recency?.tier,99)-num(y.recency?.tier,99):num(y.adjusted_total)-num(x.adjusted_total));let h='<table class="table"><thead><tr><th>#</th><th>股票</th><th>池</th><th>P</th><th>调整分</th><th>涨幅</th><th>三共振</th></tr></thead><tbody>';a.forEach((r,i)=>h+=`<tr><td>${i+1}</td><td><b>${r.name||'-'}</b><br><span class="muted">${r.code||'-'} · ${r.sector||'-'}</span></td><td>${r.pool||'-'}</td><td>P${r.recency?.tier??'-'}</td><td>${Number(r.adjusted_total||0).toFixed(1)}</td><td class="${num(r.change_pct)>=0?'up':'down'}">${num(r.change_pct).toFixed(1)}%</td><td>${r.resonance?.count??0}/3</td></tr>`);h+='</tbody></table>';document.getElementById('rows').innerHTML=h}['q','pool','sort'].forEach(x=>document.getElementById(x).addEventListener('input',render));</script></body></html>''')
    return t.substitute(DATE=esc(d.get('scan_date')),TIME=esc(d.get('scan_time')),MODEL=esc(d.get('model')),MOOD=mood,ACTION=esc(a),DESC=esc(desc),SCORE=f'{num(s.get("sentiment_score")):.1f}',LABEL=esc(s.get('sentiment_label','正常')),LUP=esc(s.get('limit_up_count')),LDN=esc(s.get('limit_down_count')),MAX=esc(s.get('max_boards_est')),EXP=esc(s.get('explosion_rate')),FOCUS=len(focus),READY=ready,WATCH=watch,TOTAL=len(c),FOCUS_HTML=''.join(focus_card(r,i+1) for i,r in enumerate(focus)) or '<div class="empty">当前没有重点观察股。</div>',SECTOR=sec or '<div class="empty">暂无板块数据。</div>',CONCEPT=con or '<div class="empty">暂无概念数据。</div>',EF=ef or '<span class="mini">20:00 尚未运行</span>',EN=news(e.get('headlines') or [],'等待20:00晚间信息更新。'),MS=ms,MN=news(m.get('overnight_headlines') or [],'等待08:00隔夜信息更新。'))

def main():
    d=load(LATEST)
    if not d.get('candidates'):raise RuntimeError('candidate pool empty; refuse to overwrite dashboard')
    os.makedirs(DOCS,exist_ok=True)
    with open(OUT,'w',encoding='utf-8') as f:f.write(render(d,load(EVENING),load(MORNING)))
    print(f'[Dashboard V3] generated {OUT}; candidates={len(d.get("candidates",[]))}')
if __name__=='__main__':main()
